from pptx import Presentation
from pptx.util import Inches, Pt, Emu
import json

prs = Presentation('/root/Awesome-Agent-Papers.pptx')

slide_width = prs.slide_width
slide_height = prs.slide_height
print(f"Slide dimensions: {slide_width} x {slide_height} EMU")
print(f"Slide dimensions: {slide_width/914400:.2f} x {slide_height/914400:.2f} inches")
print(f"Total slides: {len(prs.slides)}")
print()

for slide_idx, slide in enumerate(prs.slides):
    print(f"=== Slide {slide_idx + 1} ===")
    for shape_idx, shape in enumerate(slide.shapes):
        print(f"  Shape {shape_idx}: type={shape.shape_type}, name='{shape.name}'")
        print(f"    Position: left={shape.left}, top={shape.top}, width={shape.width}, height={shape.height}")
        if shape.has_text_frame:
            for para_idx, para in enumerate(shape.text_frame.paragraphs):
                text = para.text.strip()
                if text:
                    runs_info = []
                    for run in para.runs:
                        try:
                            color_rgb = str(run.font.color.rgb) if run.font.color and run.font.color.type is not None else None
                        except:
                            color_rgb = None
                        runs_info.append({
                            'text': run.text,
                            'bold': run.font.bold,
                            'size': str(run.font.size) if run.font.size else None,
                            'color': color_rgb,
                            'font_name': run.font.name
                        })
                    if len(text) > 100:
                        print(f"    Para {para_idx}: '{text[:100]}...'")
                    else:
                        print(f"    Para {para_idx}: '{text}'")
                    if runs_info:
                        print(f"      Runs: {json.dumps(runs_info)}")
    print()
PYEOF
